suppressMessages({library(targets); library(dplyr); library(ggplot2); library(tidyr)})
ph <- bind_rows(tar_read_raw("old_buoy_wq") |> filter(var_aeme == "CHM_ph") |> transmute(Date, depth, value, src = "old buoy"),
                tar_read_raw("aeme_buoy_data") |> filter(var_aeme == "CHM_ph") |> transmute(Date, depth, value, src = "new buoy")) |> filter(is.finite(value))
ph$day <- as.Date(ph$Date); ph$yr <- as.integer(format(ph$day, "%Y")); ph$mo <- as.integer(format(ph$day, "%m"))
cat("n", nrow(ph), "\n"); print(ph |> group_by(src) |> summarise(n = n(), from = min(day), to = max(day), depths = paste(sort(unique(round(depth)))[1:min(8, n_distinct(round(depth)))], collapse = ","), q = paste(round(quantile(value, c(.01, .05, .5, .95, .99)), 2), collapse = " ")))
cat("\nvalues outside 4-11:", sum(ph$value < 4 | ph$value > 11), "\n"); ph <- ph |> filter(value > 4, value < 11)
cat("\nby year (all depths): n days, median, p05, p95, frac>8, frac<6.5\n")
print(ph |> group_by(src, yr) |> summarise(days = n_distinct(day), med = median(value), p05 = quantile(value, .05), p95 = quantile(value, .95), f_gt8 = mean(value > 8), f_lt65 = mean(value < 6.5), .groups = "drop") |> mutate(across(where(is.numeric), \(x) round(x, 2))), n = 40)
cat("\nby month (surface <=5 m):\n")
print(ph |> filter(depth <= 5) |> group_by(mo) |> summarise(n = n(), med = median(value), p05 = quantile(value, .05), p95 = quantile(value, .95), .groups = "drop") |> mutate(across(where(is.numeric), \(x) round(x, 2))))
cat("\nby depth class:\n"); print(ph |> mutate(dc = cut(depth, c(-1, 2, 5, 10, 15, 25, 40))) |> group_by(dc) |> summarise(n = n(), med = median(value), p05 = quantile(value, .05), p95 = quantile(value, .95), .groups = "drop") |> mutate(across(where(is.numeric), \(x) round(x, 2))))
# implied fpH for candidate (pH_opt, sigma)
fp <- function(p, o, s) exp(-(p - o)^2 / (2 * s^2))
cat("\nimplied mean fpH over all observations, by (pH_opt, sigma):\n")
g <- expand.grid(pH_opt = c(6.5, 7, 7.5), sigma = c(0.5, 1, 1.5)); g$mean_fpH <- mapply(\(o, s) mean(fp(ph$value, o, s)), g$pH_opt, g$sigma); g$p05 <- mapply(\(o, s) quantile(fp(ph$value, o, s), .05), g$pH_opt, g$sigma); print(round(g, 3))
# diurnal and relation to oxygen / chl
ox <- tar_read_raw("aeme_buoy_data") |> filter(var_aeme == "CHM_oxy") |> transmute(Date, depth, oxy = value)
j <- ph |> filter(src == "new buoy") |> inner_join(ox, by = c("Date", "depth")); cat("\npH vs DO (new buoy, same time/depth): n", nrow(j), " r =", round(cor(j$value, j$oxy), 2), "\n")
ph$hr <- as.integer(format(ph$Date, "%H")); cat("diurnal range of pH, surface (new buoy, hourly means):\n"); print(ph |> filter(src == "new buoy", depth <= 3) |> group_by(hr) |> summarise(med = round(median(value), 2)) |> t())
d <- ph |> group_by(src, day = format(day, "%Y-%m")) |> summarise(v = median(value), .groups = "drop") |> mutate(day = as.Date(paste0(day, "-01")))
dir.create("website/images/alum_calib", showWarnings = FALSE)
ggsave("website/images/alum_calib/ph_buoy.png", ggplot(ph |> filter(depth <= 5), aes(as.Date(Date), value, colour = src)) + geom_point(size = 0.2, alpha = 0.3) + geom_hline(yintercept = c(6, 8), linetype = 2) + labs(x = NULL, y = "pH (surface, <=5 m)", colour = NULL) + theme_minimal(base_size = 10), width = 9, height = 4, dpi = 120, bg = "white")
saveRDS(ph, "calibration/alum/ph_obs.rds")
